import{_ as t,o as a,c as l,a3 as o}from"./chunks/framework.D1iekJsc.js";const m=JSON.parse('{"title":"Recommended local models","description":"Local LLM size tips by VRAM (path check, roleplay, Chinese) for Ollama, LM Studio, KoboldCPP, llama.cpp with MiniTavern.","frontmatter":{"title":"Recommended local models","description":"Local LLM size tips by VRAM (path check, roleplay, Chinese) for Ollama, LM Studio, KoboldCPP, llama.cpp with MiniTavern.","head":[["meta",{"name":"keywords","content":"tavern,AI tavern,MiniTavern,AI companion,AI friend,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobile,Silly Tavern Android,Silly Tavern iOS,AI roleplay,character card,AI chat,mobile AI,offline AI,AI story,local LLM,Ollama,LM Studio,lorebook,regex,BYOK,user guide,docs,AI chat client"}],["meta",{"property":"og:title","content":"Recommended local models · MiniTavern Docs"}],["meta",{"property":"og:description","content":"Local LLM size tips by VRAM (path check, roleplay, Chinese) for Ollama, LM Studio, KoboldCPP, llama.cpp with MiniTavern."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/en/local/models"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/en/local/models"}]]},"headers":[],"relativePath":"en/local/models.md","filePath":"en/local/models.md","lastUpdated":1787224147000}'),i={name:"en/local/models.md"};function s(n,e,r,d,h,c){return a(),l("div",null,[...e[0]||(e[0]=[o(`<h1 id="recommended-models" tabindex="-1">Recommended models <a class="header-anchor" href="#recommended-models" aria-label="Permalink to &quot;Recommended models&quot;">​</a></h1><p>Names and download steps differ by tool; the table is about <strong>size and purpose</strong>. Exact pull / filenames follow each tool’s page.</p><h2 id="pick-size-by-hardware" tabindex="-1">Pick size by hardware <a class="header-anchor" href="#pick-size-by-hardware" aria-label="Permalink to &quot;Pick size by hardware&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Rough size</th><th>RAM/VRAM rough guide</th><th>Best for</th></tr></thead><tbody><tr><td>1B–3B</td><td>~4–8GB</td><td><strong>Verify the path first</strong>, low-end machines</td></tr><tr><td>7B–9B</td><td>~8–16GB</td><td>Common sweet spot for roleplay</td></tr><tr><td>12B–14B</td><td>16GB+</td><td>Better quality; speed depends on GPU</td></tr><tr><td>32B+</td><td>24GB+ or heavy quant</td><td>High-end; phone waits longer too</td></tr></tbody></table><p>Smaller quants (Q4 / Q5 / IQ, etc.) use less resource with a quality trade-off. For GGUF, community favorites are often <code>Q4_K_M</code> / <code>Q5_K_M</code>.</p><h2 id="verify-the-path-prefer-small-models" tabindex="-1">Verify the path (prefer small models) <a class="header-anchor" href="#verify-the-path-prefer-small-models" aria-label="Permalink to &quot;Verify the path (prefer small models)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>Ollama example</th><th>GGUF / other</th></tr></thead><tbody><tr><td>Fastest path check</td><td><code>llama3.2:3b</code>, <code>qwen2.5:3b</code></td><td>Any ~3B instruct GGUF</td></tr><tr><td>Light Chinese</td><td><code>qwen2.5:3b</code> / <code>qwen2.5:7b</code></td><td>Qwen2.5 Instruct quant</td></tr></tbody></table><p>Get <a href="/ultra_guides/en/connect-app/minitavern">Test succeeding</a> first, then move up in size.</p><h2 id="roleplay-tips" tabindex="-1">Roleplay tips <a class="header-anchor" href="#roleplay-tips" aria-label="Permalink to &quot;Roleplay tips&quot;">​</a></h2><ul><li>Prefer <strong>Instruct / Chat</strong> finetunes, not raw base completion models.</li><li>Popular RP weights change over time; use what loads stably in your tool with enough context.</li><li>Too-small context truncates long settings / lorebooks; for ~7B try 4k–8k first, then raise with VRAM.</li><li>The <strong>model name</strong> in MiniTavern must <strong>exactly match</strong> the tool list (including tags like <code>:7b</code>).</li></ul><h2 id="common-ollama-pulls" tabindex="-1">Common Ollama pulls <a class="header-anchor" href="#common-ollama-pulls" aria-label="Permalink to &quot;Common Ollama pulls&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> llama3.2:3b</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> qwen2.5:7b</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> qwen2.5:14b</span></span></code></pre></div><p>More commands: <a href="/ultra_guides/en/ollama/models">Ollama · Download and pick models</a>.</p><h2 id="lm-studio-koboldcpp-llama-cpp" tabindex="-1">LM Studio / KoboldCPP / llama.cpp <a class="header-anchor" href="#lm-studio-koboldcpp-llama-cpp" aria-label="Permalink to &quot;LM Studio / KoboldCPP / llama.cpp&quot;">​</a></h2><ol><li>Download <strong>GGUF</strong> from <a href="https://huggingface.co/" target="_blank" rel="noreferrer">Hugging Face</a> etc. (check license and trust).</li><li>Load the same file in the tool.</li><li>After API / Server is on, copy the <strong>model id</strong> shown in the UI into MiniTavern.</li></ol><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><p><a href="./tools">Tools overview</a> → that tool’s “start server” chapter → <a href="/ultra_guides/en/connect-app/minitavern">Configure in MiniTavern</a></p>`,17)])])}const u=t(i,[["render",s]]);export{m as __pageData,u as default};
